    FILE* fp = fopen(path, "wb");
    if (!fp) return false;
    size_t written = fwrite(data, sizeof(double), count, fp);
    fclose(fp);
    return written == count;
}

size_t file_buffered_io_read_double(const char* path, double* buffer, size_t max_count) {
    if (!path || !buffer || max_count == 0) return 0;
    FILE* fp = fopen(path, "rb");
    if (!fp) return 0;
    size_t read_count = fread(buffer, sizeof(double), max_count, fp);
    fclose(fp);
    return read_count;
}

